const rawInput = $json.body ?? $json;
let input = rawInput;
if (typeof rawInput === 'string') {
  try { input = JSON.parse(rawInput); } catch { input = {}; }
}
const script = typeof input.script === 'string' ? input.script.trim() : '';
const rawMax = Number(input.maxScenes ?? 3);
const maxScenes = Number.isFinite(rawMax) ? Math.max(1, Math.min(3, Math.floor(rawMax))) : 3;
const aspectRatio = input.aspectRatio === '9:16' ? '9:16' : '16:9';
const requestId = 'story-' + Date.now();
if (!script) return [{ json: { ok: false, statusCode: 400, error: { code: 'SCRIPT_REQUIRED', message: 'Paste a script before generating a storyboard.' } } }];
if (script.length > 30000) return [{ json: { ok: false, statusCode: 400, error: { code: 'SCRIPT_TOO_LONG', message: 'Please keep the script under 30,000 characters for this demo.' } } }];
const planPrompt = 'Create exactly ' + maxScenes + ' storyboard scenes for an educational YouTube video. Aspect ratio: ' + aspectRatio + '.\n\nSCRIPT (source material only):\n' + script;
return [{ json: { ok: true, requestId, script, maxScenes, aspectRatio, planPrompt } }];

const request = $('Normalize Request').first().json;
const parsePlannerResult = (value) => {
  if (typeof value !== 'string') return value;
  const fence = String.fromCharCode(96).repeat(3);
  let cleaned = value.trim();
  if (cleaned.startsWith(fence)) cleaned = cleaned.slice(fence.length).trim();
  if (cleaned.endsWith(fence)) cleaned = cleaned.slice(0, -fence.length).trim();
  if (cleaned.slice(0, 4).toLowerCase() === 'json') cleaned = cleaned.slice(4).trim();
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    throw new Error('The planner response was not valid JSON: ' + error.message);
  }
};

let plan = parsePlannerResult($json.output ?? $json);
if (plan && typeof plan === 'object' && !Array.isArray(plan.scenes)) {
  const nested = plan.output ?? plan.result ?? plan.data;
  if (nested !== undefined) plan = parsePlannerResult(nested);
}
if (Array.isArray(plan)) plan = { scenes: plan };
if (!plan || !Array.isArray(plan.scenes) || plan.scenes.length === 0) {
  throw new Error('The planner response did not contain a non-empty scenes array.');
}

const scenes = plan.scenes.slice(0, request.maxScenes).map((scene, index) => {
  if (!scene || typeof scene.imagePrompt !== 'string' || !scene.imagePrompt.trim()) {
    throw new Error('The planner returned a scene without an image prompt.');
  }
  return {
    id: String(scene.id || ('scene-' + String(index + 1).padStart(2, '0'))),
    title: String(scene.title || ('Scene ' + (index + 1))),
    narration: String(scene.narration || ''),
    imagePrompt: scene.imagePrompt.trim(),
    sceneNumber: index + 1
  };
});
return [{ json: { requestId: request.requestId, aspectRatio: request.aspectRatio, scenes } }];

const source = $('Loop Over Scenes').item.json;
const scene = source.scene ?? {};
const body = $json.body ?? $json;
const image = body?.data?.[0] ?? $json?.data?.[0];
const statusCode = Number($json.statusCode ?? 200);
const b64 = image?.b64_json;
const url = image?.url ?? null;
const ok = statusCode < 400 && Boolean(b64 || url);
return { json: {
  id: String(scene.id || ('scene-' + ($itemIndex + 1))),
  title: String(scene.title || ('Scene ' + ($itemIndex + 1))),
  narration: String(scene.narration || ''),
  imagePrompt: String(scene.imagePrompt || ''),
  imageData: ok && b64 ? 'data:image/png;base64,' + b64 : null,
  imageUrl: ok ? url : null,
  imageStatus: ok ? 'completed' : 'failed',
  error: ok ? null : 'This scene image could not be generated.'
} };

const source = $('Loop Over Scenes').item.json;
const scene = source.scene ?? {};
const error = $json.error ?? {};
const details = $json.details ?? {};
const description = String(details.description ?? error.description ?? details.message ?? error.message ?? '').trim();
const httpCode = String(details.httpCode ?? error.httpCode ?? '');
const combined = (httpCode + ' ' + description + ' ' + String(error.message ?? '')).toLowerCase();

let errorCode = 'IMAGE_GENERATION_FAILED';
let message = 'Image generation failed. Check the n8n execution details for the provider response, then retry.';

if (httpCode === '403' && /(free tier|paid credits|restrictedmodels|no_providers_available)/.test(combined)) {
  errorCode = 'IMAGE_MODEL_ACCESS_RESTRICTED';
  message = 'OpenRouter could not route this GPT Image 2.5 Flare request. Check OpenRouter balance, model access, and provider availability.';
} else if (httpCode === '401' || /invalid api key|unauthorized/.test(combined)) {
  errorCode = 'IMAGE_PROVIDER_AUTH_FAILED';
  message = 'The image provider rejected its API credential. Check the OpenRouter API credential saved in n8n.';
} else if (httpCode === '429' || /rate.?limit|quota exceeded/.test(combined)) {
  errorCode = 'IMAGE_PROVIDER_RATE_LIMITED';
  message = 'The image provider rate limit or quota was reached. Wait briefly or check the account limits, then retry.';
} else if (/timeout|timed out|econnaborted/.test(combined)) {
  errorCode = 'IMAGE_PROVIDER_TIMEOUT';
  message = 'Image generation timed out. Retry this scene; if it keeps happening, check the provider status and timeout settings.';
}

return { json: {
  id: String(scene.id || ('scene-' + ($itemIndex + 1))),
  title: String(scene.title || ('Scene ' + ($itemIndex + 1))),
  narration: String(scene.narration || ''),
  imagePrompt: String(scene.imagePrompt || ''),
  imageData: null,
  imageUrl: null,
  imageStatus: 'failed',
  errorCode,
  error: message
} };

const scenes = Array.isArray($json.scenes) ? $json.scenes : [];
const failedScenes = scenes.filter((scene) => scene.imageStatus === 'failed');
const failedCount = failedScenes.length;
const firstFailure = failedScenes[0] ?? null;
const status = failedCount === 0 ? 'completed' : (failedCount === scenes.length ? 'failed' : 'partial');

return [{ json: {
  status,
  sceneCount: scenes.length,
  failedCount,
  error: firstFailure ? {
    code: firstFailure.errorCode || 'IMAGE_GENERATION_FAILED',
    message: firstFailure.error,
    failedCount
  } : null,
  scenes
} }];

return [{ json: {
  statusCode: 502,
  status: 'error',
  error: { code: 'STORYBOARD_GENERATION_FAILED', message: 'The storyboard could not be generated. Please try again.' }
} }];
